"""Read-only model serving with no calibration data or control-plane credentials."""
import argparse,json
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--source',default='microservice-source-v3');p.add_argument('--model-dir',default='micro-v1/development');p.add_argument('--seeds',type=int,nargs='+',default=[0]);a=p.parse_args()
ns='systems-world-model-lab';security={'allowPrivilegeEscalation':False,'readOnlyRootFilesystem':True,'capabilities':{'drop':['ALL']}}
resources={'requests':{'cpu':'300m','memory':'512Mi'},'limits':{'cpu':'2300m','memory':'4Gi'}}
mounts=[{'name':'app','mountPath':'/app','readOnly':True},{'name':'results','mountPath':'/models','subPath':a.model_dir,'readOnly':True},{'name':'results','mountPath':'/results/venv','subPath':'venv','readOnly':True},{'name':'results','mountPath':'/results/work/upstream','subPath':'work/upstream','readOnly':True},{'name':'tmp','mountPath':'/tmp'}]
labels={'swm-component':'inference','swm-role':'agent'}
spec={'automountServiceAccountToken':False,'securityContext':{'runAsNonRoot':True,'runAsUser':1000,'runAsGroup':1000,'fsGroup':1000,'seccompProfile':{'type':'RuntimeDefault'}},'nodeSelector':{'kubernetes.io/hostname':'amd-halo'},'initContainers':[{'name':'unpack','image':'python:3.11-slim','command':['sh','-ec','tar xzf /source/app.tar.gz -C /app'],'securityContext':security,'resources':resources,'volumeMounts':[{'name':'source','mountPath':'/source','readOnly':True},{'name':'app','mountPath':'/app'}]}],'containers':[{'name':'agent','image':'python:3.11-slim','command':['/results/venv/bin/python','-m','microservice.agent','--root','/models','--seeds',*[str(s) for s in a.seeds]],'env':[{'name':'PYTHONPATH','value':'/app:/app/deps:/results/work/upstream'},{'name':'DREAMER_SOURCE','value':'/results/work/upstream'},{'name':'PYTHONDONTWRITEBYTECODE','value':'1'},{'name':'PYTHONUNBUFFERED','value':'1'},{'name':'OMP_NUM_THREADS','value':'1'},{'name':'OPENBLAS_NUM_THREADS','value':'1'},{'name':'XLA_FLAGS','value':'--xla_cpu_multi_thread_eigen=false intra_op_parallelism_threads=1'},{'name':'XDG_CACHE_HOME','value':'/tmp/cache'}],'securityContext':security,'resources':resources,'volumeMounts':mounts,'readinessProbe':{'httpGet':{'path':'/health','port':8088},'periodSeconds':3}}],'volumes':[{'name':'source','configMap':{'name':a.source}},{'name':'app','emptyDir':{'sizeLimit':'32Mi'}},{'name':'results','persistentVolumeClaim':{'claimName':'results','readOnly':True}},{'name':'tmp','emptyDir':{'sizeLimit':'512Mi'}}]}
items=[{'apiVersion':'apps/v1','kind':'Deployment','metadata':{'name':'swm-inference','namespace':ns},'spec':{'replicas':1,'strategy':{'type':'Recreate'},'selector':{'matchLabels':labels},'template':{'metadata':{'labels':labels},'spec':spec}}},{'apiVersion':'v1','kind':'Service','metadata':{'name':'swm-inference','namespace':ns},'spec':{'selector':labels,'ports':[{'port':8088}]}},{'apiVersion':'networking.k8s.io/v1','kind':'NetworkPolicy','metadata':{'name':'swm-inference-api','namespace':ns},'spec':{'podSelector':{'matchLabels':{'swm-component':'inference'}},'policyTypes':['Ingress'],'ingress':[{'from':[{'podSelector':{'matchLabels':{'swm-role':role}}} for role in ('runner','agent')],'ports':[{'port':8088}]}]}},{'apiVersion':'networking.k8s.io/v1','kind':'NetworkPolicy','metadata':{'name':'swm-runner-inference','namespace':ns},'spec':{'podSelector':{'matchLabels':{'swm-role':'runner'}},'policyTypes':['Egress'],'egress':[{'to':[{'podSelector':{'matchLabels':{'swm-component':'inference'}}}],'ports':[{'port':8088}]}]}}]
items.append({'apiVersion':'networking.k8s.io/v1','kind':'NetworkPolicy','metadata':{'name':'swm-agent-self-api','namespace':ns},'spec':{'podSelector':{'matchLabels':{'swm-role':'agent'}},'policyTypes':['Egress'],'egress':[{'to':[{'podSelector':{'matchLabels':{'swm-component':'inference'}}}],'ports':[{'port':8088}]}]}})
